mapper.sql:
WHERE i.interview_is_deleted_yn = 'N'

    AND i.company_nm = #{companyNm}


    AND (i.company_nm LIKE CONCAT('%', #{keyword}, '%') OR i.job_nm LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT i.interview_review_sq, i.user_sq, u.user_nickname, i.company_nm, i.job_nm, i.career_level, i.interview_dt, i.difficulty_star, i.result_cd, i.interview_view_cnt, i.interview_created_at_dtm FROM TBL_INTERVIEW_REVIEW_M i LEFT JOIN TBL_USER_M u ON u.user_sq = i.user_sq
ORDER BY i.interview_created_at_dtm ASC ORDER BY i.interview_view_cnt DESC ORDER BY i.interview_created_at_dtm DESC
LIMIT #{size} OFFSET #{offset}
